import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Start here","description":"Understand Ordo Knowledge Lab and choose a reading path.","frontmatter":{"title":"Start here","description":"Understand Ordo Knowledge Lab and choose a reading path."},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1794376220000}'),i={name:"guide/index.md"};function n(s,e,d,h,c,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h1><p><strong>Ordo Knowledge Lab turns source material into a portable, evidence-backed library you can maintain and chat with.</strong> It is an IS373 teaching project built by selectively reusing Ordo&#39;s existing code.</p><h2 id="choose-your-path" tabindex="-1">Choose your path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to &quot;Choose your path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your question</th><th>Read next</th></tr></thead><tbody><tr><td>I&#39;m taking IS373 now</td><td><a href="./../students/">Finish your current RAG assignment</a></td></tr><tr><td>Why build this?</td><td><a href="./vision">Project vision</a></td></tr><tr><td>What would it do?</td><td><a href="./capabilities">Capabilities</a>, then <a href="./walkthrough">a research walkthrough</a></td></tr><tr><td>How does it work?</td><td><a href="./../design/">System design</a></td></tr><tr><td>What should we build first?</td><td><a href="./../build/">Build guide</a> and <a href="./../project/roadmap">delivery roadmap</a></td></tr><tr><td>What can I run today?</td><td><a href="./../project/setup">Local documentation setup</a> and <a href="./../engineering/examples">executable examples</a></td></tr><tr><td>Where did the design come from?</td><td><a href="./../reuse/">Ordo reuse map</a> and <a href="./../reference/">reference library</a></td></tr></tbody></table><h2 id="the-idea-in-one-minute" tabindex="-1">The idea in one minute <a class="header-anchor" href="#the-idea-in-one-minute" aria-label="Permalink to &quot;The idea in one minute&quot;">​</a></h2><p>Sources become preserved artifacts. Extractors propose mentions, identities and claims. Reviewers resolve ambiguity and approve a revision. Search retrieves evidence from that revision; chat explains it with citations. Export moves the published library without requiring the original processing hardware.</p><p>The rule is <strong>canonical identity, not canonical truth</strong>: one incident can have conflicting accounts. Resolving its identity does not erase disagreement.</p><h2 id="what-exists-today" tabindex="-1">What exists today <a class="header-anchor" href="#what-exists-today" aria-label="Permalink to &quot;What exists today&quot;">​</a></h2><p>The repository contains these docs, runnable synthetic contract labs and a separately tested Svelte welcome-page scaffold. The research backend, interactive research interface and native workers remain planned. A passing documentation test is not proof of a working research application. <a href="./../status">Check status and evidence</a>.</p><h2 id="how-to-read-these-docs" tabindex="-1">How to read these docs <a class="header-anchor" href="#how-to-read-these-docs" aria-label="Permalink to &quot;How to read these docs&quot;">​</a></h2><p><strong>Start</strong> explains the purpose. <strong>Design</strong> owns the current architecture. <strong>Build</strong> connects existing code to implementation and tests. <strong>Reference</strong> preserves audits, terminology and earlier alternatives.</p><p>Requirements live in one <a href="./../project/acceptance">acceptance register</a>. The <a href="./../project/roadmap">S0–S7 roadmap</a> owns implementation order. Historical material stays visible but does not override the current plan.</p><p><strong>Next:</strong> <a href="./vision">Read the vision →</a></p>',13)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
